def organise(codes):
    valid = []
    for code in codes:
        if 3 <= len(code) <= 4 and all('A'<=c<='Z' for c in code[:2]) and all('0'<=c<='9' for c in code[2:]) and code[2]!='0': valid.append(code)
    def key(code): return (int(code[2:]),code[:2])
    for i in range(1,len(valid)):
        value,j = valid[i],i-1
        while j>=0 and key(valid[j])>key(value): valid[j+1]=valid[j];j-=1
        valid[j+1]=value
    return [[c for c in valid if int(c[2:])%2==0],[c for c in valid if int(c[2:])%2==1]]
